  }
  $u=$conn->prepare('UPDATE attendance_change_requests SET status=?,reviewed_by=?,reviewed_at=NOW(),review_notes=? WHERE id=? AND school_id=?');$u->bind_param('sisii',$decision,$user,$notes,$id,$school);if(!$u->execute())throw new Exception($u->error);$u->close();auditAttendance($conn,$school,$attendance,0,$decision==='Aprobada'?'attendance_request_approved':'attendance_request_rejected',['request_id'=>$id,'type'=>$request['request_type'],'notes'=>$notes]);
  if(atable($conn,'notification_events')){$recipient=(int)$request['requested_by'];$eventType='Resultado de asistencia';$priority=$decision==='Aprobada'?'Normal':'Alta';$title=$decision==='Aprobada'?'Solicitud de asistencia aprobada':'Solicitud de asistencia rechazada';$message=$request['request_type'].($notes!==''?' · '.$notes:'');$sourceType='attendance_request_result';$event=$conn->prepare('INSERT INTO notification_events(school_id,recipient_user_id,notification_type,priority,title,message,source_type,source_id,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$event->bind_param('iisssssii',$school,$recipient,$eventType,$priority,$title,$message,$sourceType,$id,$user);if(!$event->execute())throw new Exception($event->error);$event->close();}
