if($action==='save_rules'){$rows=json_decode($_POST['rules']??'[]',true);if(!is_array($rows))ao(['status'=>0,'message'=>'Las reglas no son válidas.']);$days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];$conn->begin_transaction();try{foreach($rows as $r){$day=$r['day']??'';if(!in_array($day,$days,true))continue;$active=!empty($r['active'])?1:0;$entry=$r['entry']??'07:30';$tol=max(0,min(180,(int)($r['tolerance']??0)));$exit=$r['exit']??'15:00';$earlyExit=$r['early_exit']??$exit;$late=date('H:i:s',strtotime($entry)+$tol*60);$entry.=':'.(strlen($entry)===5?'00':'');$exit.=':'.(strlen($exit)===5?'00':'');$earlyExit.=':'.(strlen($earlyExit)===5?'00':'');$name=['Monday'=>'Lunes','Tuesday'=>'Martes','Wednesday'=>'Miércoles','Thursday'=>'Jueves','Friday'=>'Viernes','Saturday'=>'Sábado','Sunday'=>'Domingo'][$day];$s=$conn->prepare("INSERT INTO attendance_rules(school_id,day_of_week,early_time,late_time,day_name_es,entry_time,tolerance_minutes,exit_time,early_exit_limit,is_active) VALUES(?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE early_time=VALUES(early_time),late_time=VALUES(late_time),day_name_es=VALUES(day_name_es),entry_time=VALUES(entry_time),tolerance_minutes=VALUES(tolerance_minutes),exit_time=VALUES(exit_time),early_exit_limit=VALUES(early_exit_limit),is_active=VALUES(is_active)");$s->bind_param('isssssissi',$school,$day,$entry,$late,$name,$entry,$tol,$exit,$earlyExit,$active);if(!$s->execute())throw new Exception($s->error);$s->close();}$conn->commit();ao(['status'=>1,'message'=>'Reglas guardadas correctamente.']);}catch(Throwable $e){$conn->rollback();ao(['status'=>0,'message'=>$e->getMessage()]);}}
